import random, subprocess, sys
from functools import lru_cache

def run(pid, inp):
    return subprocess.run([sys.executable,f'solutions/{pid}.py'],input=inp.encode(),stdout=subprocess.PIPE,check=True).stdout.decode().strip()

def brute(arr,L,R):
    a=arr[L:R+1]
    @lru_cache(None)
    def f(mask):
        # first available
        try: i=(mask & -mask).bit_length()-1
        except: return 0
        # actually bit 1 unavailable
        m=mask; i=0
        while m&1:
            i+=1; m>>=1
        best=f(mask | (1<<i))  # skip i
        for j in range(i+1,len(a)):
            if not (mask>>j)&1 and 2*a[i]<=a[j]:
                best=max(best,1+f(mask | (1<<i) | (1<<j)))
        return best
    return f(0)

